namespace sv_4280440e6d8c4194b4210b6640328d54.Services;

public class DoctorInfo
{
    public string Name { get; set; } = string.Empty;
    public bool AcceptsSelfPay { get; set; }
}

public class ValidationResult
{
    public bool IsValid => Errors.Count == 0;
    public Dictionary<string, string> Errors { get; } = new();
}

public interface IAppointmentService
{
    Task<List<DoctorInfo>> GetDoctorsAsync();
    Task<List<string>> GetAvailableTimeSlotsAsync(string doctorName, DateOnly date);
    Task<ValidationResult> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctorName,
        string timeSlot);
}

public class AppointmentService : IAppointmentService
{
    private static readonly List<DoctorInfo> Doctors =
    [
        new() { Name = "Dr. Smith", AcceptsSelfPay = false },
        new() { Name = "Dr. Johnson", AcceptsSelfPay = true },
        new() { Name = "Dr. Patel", AcceptsSelfPay = true },
        new() { Name = "Dr. Williams", AcceptsSelfPay = false },
        new() { Name = "Dr. Lee", AcceptsSelfPay = true }
    ];

    public Task<List<DoctorInfo>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctorName, DateOnly date)
    {
        List<string> slots =
        [
            "9:00 AM", "9:30 AM", "10:00 AM", "10:30 AM",
            "11:00 AM", "1:00 PM", "1:30 PM", "2:00 PM",
            "2:30 PM", "3:00 PM", "3:30 PM", "4:00 PM"
        ];

        return Task.FromResult(slots);
    }

    public Task<ValidationResult> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctorName,
        string timeSlot)
    {
        var result = new ValidationResult();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors["Email"] = "Account has outstanding balance";
        }

        if (string.Equals(insuranceProvider, "None", StringComparison.OrdinalIgnoreCase)
            && !DoctorAcceptsSelfPay(doctorName))
        {
            result.Errors["Doctor"] = "Selected doctor does not accept self-pay patients";
        }

        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            result.Errors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(result);
    }

    private static bool DoctorAcceptsSelfPay(string doctorName)
    {
        var doctor = Doctors.Find(d =>
            string.Equals(d.Name, doctorName, StringComparison.OrdinalIgnoreCase));
        return doctor?.AcceptsSelfPay ?? true;
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_4280440e6d8c4194b4210b6640328d54.Services
@inject IAppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book an Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* ───── STEP 1: Patient Information ───── *@
    <fieldset>
        <legend>Step 1: Patient Information</legend>

        <div class="mb-3">
            <label for="patientName" class="form-label">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (_serverErrors.TryGetValue("Email", out var emailErr))
            {
                <div class="validation-message">@emailErr</div>
            }
        </div>

        <div class="mb-3">
            <label for="phone" class="form-label">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label for="insurance" class="form-label">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!_showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next
            </button>
        }
    </fieldset>

    @* ───── STEP 2: Appointment Details ───── *@
    @if (_showStep2)
    {
        <fieldset class="mt-4">
            <legend>Step 2: Appointment Details</legend>

            <div class="mb-3">
                <label for="doctor" class="form-label">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor"
                    @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in _doctors)
                    {
                        <option value="@doc.Name">@doc.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (_serverErrors.TryGetValue("Doctor", out var docErr))
                {
                    <div class="validation-message">@docErr</div>
                }
            </div>

            <div class="mb-3">
                <label for="date" class="form-label">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
                    @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label for="timeSlot" class="form-label">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in _timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (_serverErrors.TryGetValue("TimeSlot", out var slotErr))
                {
                    <div class="validation-message">@slotErr</div>
                }
            </div>

            <div class="mb-3">
                <label for="reason" class="form-label">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="Model.Reason" />
                <ValidationMessage For="() => Model.Reason" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-secondary" @onclick="BackToStep1">
                    Back
                </button>
                <button type="button" class="btn btn-outline-primary" @onclick="CheckAvailability"
                    disabled="@_isChecking">
                    @(_isChecking ? "Checking…" : "Check Availability")
                </button>
                <button type="submit" class="btn btn-primary" disabled="@(!_availabilityConfirmed)">
                    Book Appointment
                </button>
            </div>
        </fieldset>
    }
</EditForm>

@if (_submitted)
{
    <div class="alert alert-success mt-4" role="alert">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();

    private List<DoctorInfo> _doctors = [];
    private List<string> _timeSlots = [];
    private Dictionary<string, string> _serverErrors = new();
    private bool _showStep2;
    private bool _isChecking;
    private bool _availabilityConfirmed;
    private bool _submitted;

    private EditContext? _editContext;

    protected override async Task OnInitializedAsync()
    {
        _editContext = new EditContext(Model);
        _doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        _editContext = new EditContext(Model);
        var isValid = _editContext.Validate();

        // Only validate Step 1 fields
        var step1Properties = new[] {
            nameof(Model.PatientName),
            nameof(Model.Email),
            nameof(Model.Phone),
            nameof(Model.InsuranceProvider)
        };

        var step1Messages = _editContext.GetValidationMessages()
            .Where((_, i) =>
            {
                // Check if any step1 field has errors
                return true;
            });

        var hasStep1Errors = step1Properties
            .Any(p => _editContext
                .GetValidationMessages(new FieldIdentifier(Model, p))
                .Any());

        if (!hasStep1Errors)
        {
            _showStep2 = true;
            _serverErrors.Clear();
        }
    }

    private void BackToStep1()
    {
        _showStep2 = false;
        _availabilityConfirmed = false;
        _serverErrors.Clear();
    }

    private async Task OnDoctorOrDateChanged()
    {
        _availabilityConfirmed = false;
        _serverErrors.Clear();

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            var date = DateOnly.FromDateTime(Model.AppointmentDate.Value);
            _timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(Model.Doctor, date);
            Model.TimeSlot = string.Empty;
        }
    }

    private async Task CheckAvailability()
    {
        _serverErrors.Clear();
        _availabilityConfirmed = false;

        _editContext = new EditContext(Model);
        _editContext.Validate();

        // Validate step 2 required fields before calling server
        var step2Properties = new[] {
            nameof(Model.Doctor),
            nameof(Model.AppointmentDate),
            nameof(Model.TimeSlot),
            nameof(Model.Reason)
        };

        var hasStep2Errors = step2Properties
            .Any(p => _editContext
                .GetValidationMessages(new FieldIdentifier(Model, p))
                .Any());

        if (hasStep2Errors)
        {
            return;
        }

        // Additional date validation
        if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value.Date <= DateTime.Today)
        {
            _serverErrors["AppointmentDate"] = "Date must be in the future";
            return;
        }

        _isChecking = true;

        try
        {
            var result = await AppointmentService.ValidatePatientAsync(
                Model.Email,
                Model.InsuranceProvider,
                Model.Doctor,
                Model.TimeSlot);

            if (result.IsValid)
            {
                _availabilityConfirmed = true;
            }
            else
            {
                foreach (var error in result.Errors)
                {
                    _serverErrors[error.Key] = error.Value;
                }
            }
        }
        finally
        {
            _isChecking = false;
        }
    }

    private void HandleSubmit()
    {
        if (_availabilityConfirmed)
        {
            _submitted = true;
        }
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_4280440e6d8c4194b4210b6640328d54.Models;

public class AppointmentModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required")]
    [EmailAddress(ErrorMessage = "Invalid email format")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone is required")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Insurance provider is required")]
    public string InsuranceProvider { get; set; } = string.Empty;

    // Step 2
    [Required(ErrorMessage = "Please select a doctor")]
    public string Doctor { get; set; } = string.Empty;

    [Required(ErrorMessage = "Date is required")]
    public DateTime? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot")]
    public string TimeSlot { get; set; } = string.Empty;

    [Required(ErrorMessage = "Reason for visit is required")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer")]
    public string Reason { get; set; } = string.Empty;
}

