+            </div>
+        </fieldset>
+    }
+</EditForm>
+
+@if (_submitted)
+{
+    <div class="alert alert-success mt-4" role="alert">
+        Appointment booked successfully!
+    </div>
+}
+
+@code {
+    private AppointmentModel Model { get; set; } = new();
+
+    private List<DoctorInfo> _doctors = [];
+    private List<string> _timeSlots = [];
+    private Dictionary<string, string> _serverErrors = new();
+    private bool _showStep2;
+    private bool _isChecking;
+    private bool _availabilityConfirmed;
+    private bool _submitted;
+
+    private EditContext? _editContext;
+
+    protected override async Task OnInitializedAsync()
+    {
+        _editContext = new EditContext(Model);
+        _doctors = await AppointmentService.GetDoctorsAsync();
+    }
+
+    private void ProceedToStep2()
+    {
+        _editContext = new EditContext(Model);
+        var isValid = _editContext.Validate();
+
+        // Only validate Step 1 fields
+        var step1Properties = new[] {
+            nameof(Model.PatientName),
+            nameof(Model.Email),
+            nameof(Model.Phone),
+            nameof(Model.InsuranceProvider)
+        };
+
+        var step1Messages = _editContext.GetValidationMessages()
+            .Where((_, i) =>
+            {
+                // Check if any step1 field has errors
+                return true;
+            });
+
+        var hasStep1Errors = step1Properties
+            .Any(p => _editContext
+                .GetValidationMessages(new FieldIdentifier(Model, p))
+                .Any());
+
+        if (!hasStep1Errors)
+        {
+            _showStep2 = true;
+            _serverErrors.Clear();
+        }
+    }
+
+    private void BackToStep1()
+    {
+        _showStep2 = false;
+        _availabilityConfirmed = false;
+        _serverErrors.Clear();
+    }
+
+    private async Task OnDoctorOrDateChanged()
+    {
+        _availabilityConfirmed = false;
+        _serverErrors.Clear();
+
+        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
+        {
+            var date = DateOnly.FromDateTime(Model.AppointmentDate.Value);
+            _timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(Model.Doctor, date);
+            Model.TimeSlot = string.Empty;
+        }
+    }
+
+    private async Task CheckAvailability()
+    {
+        _serverErrors.Clear();
+        _availabilityConfirmed = false;
+
+        _editContext = new EditContext(Model);
+        _editContext.Validate();
+
+        // Validate step 2 required fields before calling server
+        var step2Properties = new[] {
+            nameof(Model.Doctor),
+            nameof(Model.AppointmentDate),
+            nameof(Model.TimeSlot),
+            nameof(Model.Reason)
+        };
+
+        var hasStep2Errors = step2Properties
+            .Any(p => _editContext
+                .GetValidationMessages(new FieldIdentifier(Model, p))
+                .Any());
+
+        if (hasStep2Errors)
+        {
+            return;
+        }
+
+        // Additional date validation
+        if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value.Date <= DateTime.Today)
+        {
+            _serverErrors["AppointmentDate"] = "Date must be in the future";
+            return;
+        }
+
+        _isChecking = true;
+
+        try
+        {
+            var result = await AppointmentService.ValidatePatientAsync(
+                Model.Email,
+                Model.InsuranceProvider,
+                Model.Doctor,
+                Model.TimeSlot);
+
+            if (result.IsValid)
+            {
+                _availabilityConfirmed = true;
+            }
+            else
+            {
+                foreach (var error in result.Errors)
+                {
+                    _serverErrors[error.Key] = error.Value;
+                }
+            }
+        }
+        finally
+        {
+            _isChecking = false;
+        }
+    }
+
+    private void HandleSubmit()
+    {
+        if (_availabilityConfirmed)
+        {
+            _submitted = true;
+        }
+    }
+}
